#!/usr/bin/env python3
"""
Generate navigable INDEX.md and INDEX.json from the repo artifacts.
Runs in GitHub Actions on every push; can also run locally:
    python3 .github/scripts/generate_index.py
"""
import json
import os
import re
import sys
from pathlib import Path
from collections import Counter

REPO_ROOT = Path(__file__).parent.parent.parent
print(f"Repo root: {REPO_ROOT}")

# === 1. Collect research/decompiled/ ===
decompiled_dir = REPO_ROOT / "research" / "decompiled"
functions = []
if decompiled_dir.exists():
    for f in sorted(decompiled_dir.glob("*.c")):
        # Read the file header comment
        head = ""
        try:
            with open(f, encoding="utf-8") as fh:
                head = fh.read(2000)
        except:
            pass
        # Extract metadata from the comment
        name = f.stem
        addr = ""
        reason = ""
        for line in head.split("\n"):
            m = re.match(r'//\s*Function:\s*(.+)', line)
            if m:
                name = m.group(1).strip()
            m = re.match(r'//\s*Address:\s*(\S+)', line)
            if m:
                addr = m.group(1)
            m = re.match(r'//\s*Reason:\s*(.+)', line)
            if m:
                reason = m.group(1).strip()
        functions.append({
            "name": name,
            "address": addr,
            "file": str(f.relative_to(REPO_ROOT)),
            "reason": reason,
            "size_bytes": f.stat().st_size,
        })

# === 2. Collect research/binary_data/functions/ ===
bd_funcs_dir = REPO_ROOT / "research" / "binary_data" / "functions"
bd_funcs = []
if bd_funcs_dir.exists():
    for f in sorted(bd_funcs_dir.glob("*.json")):
        try:
            with open(f) as fh:
                d = json.load(fh)
            bd_funcs.append({
                "address": d.get("address", f.stem),
                "name": d.get("name", ""),
                "isThunk": d.get("isThunk", False),
                "isExternal": d.get("isExternal", False),
                "file": str(f.relative_to(REPO_ROOT)),
                "decompiled_size": len(d.get("decompiled", "")),
            })
        except Exception as e:
            print(f"  WARN: {f}: {e}", file=sys.stderr)

# === 3. Collect research/binary_data/ artifacts ===
bd_artifacts = {}
binary_data = REPO_ROOT / "research" / "binary_data"
if binary_data.exists():
    for root, dirs, files in os.walk(binary_data):
        for f in files:
            p = Path(root) / f
            rel = str(p.relative_to(REPO_ROOT))
            # Skip functions/ (already handled)
            if "functions/" in rel:
                continue
            category = "other"
            if "strings/" in rel:
                category = "strings"
            elif "types/" in rel:
                category = "types"
            elif "segments/" in rel:
                category = "segments"
            elif "callgraph/" in rel:
                category = "callgraph"
            bd_artifacts.setdefault(category, []).append({
                "file": rel,
                "size_bytes": p.stat().st_size,
            })

# === 4. Statistics ===
stats = {
    "total_functions_in_binary": 4092,
    "decompiled_c_files": len(functions),
    "binary_data_function_jsons": len(bd_funcs),
    "total_coverage_pct": round(len(bd_funcs) / 4092 * 100, 2),
    "binary_data_categories": {k: len(v) for k, v in bd_artifacts.items()},
}

# === 5. INDEX.json ===
index = {
    "target": "DaybreakDX.exe",
    "target_info": {
        "format": "PE32",
        "arch": "x86 32-bit LE",
        "image_base": "0x00400000",
        "total_functions": 4092,
    },
    "stats": stats,
    "functions": functions,
    "binary_data_functions": bd_funcs,
    "binary_data_artifacts": bd_artifacts,
    "documents": [
        "README.md",
        "docs/overview.md",
        "docs/status.md",
    ],
}

with open(REPO_ROOT / "INDEX.json", "w", encoding="utf-8") as f:
    json.dump(index, f, indent=2, ensure_ascii=False)
print(f"INDEX.json: {len(json.dumps(index))} chars")

# === 6. INDEX.md (human-readable) ===
md = []
md.append("# Index — DaybreakDX.exe Decompilation")
md.append("")
md.append("> Auto-generated by the GitHub Action `.github/workflows/build-index.yml`")
md.append("> Do not edit manually — edit the source artifacts and push.")
md.append("")
md.append("## Statistics")
md.append("")
md.append(f"| Metric | Value |")
md.append(f"|--------|-------|")
md.append(f"| Total functions in binary | {stats['total_functions_in_binary']:,} |")
md.append(f"| `.c` files in `research/decompiled/` | {stats['decompiled_c_files']} |")
md.append(f"| Function JSONs in `research/binary_data/functions/` | {stats['binary_data_function_jsons']:,} |")
md.append(f"| **Total coverage** | **{stats['total_coverage_pct']}%** |")
md.append("")
md.append("## Repo structure")
md.append("")
md.append("```")
md.append("daybreak-decomp/")
md.append("├── README.md                      Entry map for the whole repo")
md.append("├── INDEX.md                       This file (generated)")
md.append("├── INDEX.json                     Machine-readable index (generated)")
md.append("├── docs/                          English documentation")
md.append("│   ├── overview.md                What this repo is + key findings")
md.append("│   ├── pipeline.md                RE pipelines (how artifacts flow)")
md.append("│   ├── status.md                  Living status + metrics")
md.append("│   ├── conventions.md             C/style/commit conventions")
md.append("│   ├── agents/                    Guides for automation agents")
md.append("│   ├── reports/                   Findings summaries")
md.append("│   └── archive/                   Original Portuguese docs (historical)")
md.append("├── research/                      RE artifacts + pipelines")
md.append("│   ├── decompiled/                Raw mass dump, one .c per function (read-only)")
md.append("│   ├── recomp/                    Generated readable C (never edit by hand)")
md.append("│   ├── binary_data/               Upstream evidence (JSON store, strings, reports)")
md.append("│   ├── symbols/                   Source of truth (names, types, notes)")
md.append("│   ├── progress/                  Coverage metrics (official)")
md.append("│   ├── tools/                     ingest → generate_recomp → coverage_report")
md.append("│   └── extraction_phases/         Raw phase dumps + prioritization JSONs")
md.append("├── remake/                        Playable C++ remake (the product)")
md.append("├── tools/")
md.append("│   └── launch_original.sh         Run the original exe under Wine (repo-root relative)")
md.append("├── Higurashi-Daybreak/            Local game install (gitignored, not in repo)")
md.append("└── .github/")
md.append("    ├── workflows/build-index.yml  Action that generates this index")
md.append("    └── scripts/generate_index.py  Generator script")
md.append("```")
md.append("")
md.append("## Decompiled functions (`research/decompiled/`)")
md.append("")
md.append("| File | Address | Name | Reason |")
md.append("|------|---------|------|--------|")
for fn in functions[:50]:
    md.append(f"| `{fn['file']}` | `{fn['address']}` | `{fn['name']}` | {fn['reason']} |")
if len(functions) > 50:
    md.append(f"| ... | ... | ... | _(and {len(functions)-50} more functions)_ |")
md.append("")
md.append("## Artifacts in `research/binary_data/`")
md.append("")
for cat, files in bd_artifacts.items():
    md.append(f"### `{cat}/` ({len(files)} files)")
    md.append("")
    for f in files[:20]:
        md.append(f"- `{f['file']}` ({f['size_bytes']:,} bytes)")
    if len(files) > 20:
        md.append(f"- _(and {len(files)-20} more)_")
    md.append("")

md.append("## Documents")
md.append("")
for d in index.get("documents", []):
    md.append(f"- [`{d}`]({d})")
md.append("")
md.append("---")
md.append("")
md.append(f"Last updated: via GitHub Actions")
md.append("")

with open(REPO_ROOT / "INDEX.md", "w", encoding="utf-8") as f:
    f.write("\n".join(md))
print(f"INDEX.md: {len(chr(10).join(md))} chars")
